import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from specs5 import *

# ═════════════════════════ CUT: the enzyme of the jeans ═════════════════════════

cut_cellulase = cut_spec('cut-cellulase', B('Taking out the gene of the jeans enzyme', 'Sacar el gen de la enzima de los vaqueros'), B('A look-alike band in the gel', 'Una banda parecida en el gel'), 'intermediate', 7, 'jeans',
    B('Cut the cellulase gene out of its DNA. One enzyme gives a band the size of the gene that is not the gene.', 'Saca el gen de la celulasa de su ADN. Una enzima da una banda del tamaño del gen que no es el gen.'),
    B('The fungus that washes jeans makes its cellulase from a gene. To make the enzyme in a tank in large amounts, the gene has to be cut out of the fungus DNA first.', 'El hongo que lava los vaqueros fabrica su celulasa a partir de un gen. Para fabricar la enzima en grandes cantidades en un tanque, primero hay que sacar el gen del ADN del hongo.'),
    (B('Cellulase gene', 'Gen de la celulasa'), 4, 9.5), 15,
    [ENZ('kpn', 'KpnI', 'GGTACC', [4, 13]), ENZ('sac', 'SacI', 'GAGCTC', [1, 9.5]), ENZ('pst', 'PstI', 'CTGCAG', [6.5]), ENZ('sal', 'SalI', 'GTCGAC', [2, 7.5])],
    [B('The gene needs a cut at each end and none inside. Look at the map and at the gel: one band has the size of the gene but comes from somewhere else.', 'El gen necesita un corte en cada extremo y ninguno dentro. Mira el mapa y el gel: una banda tiene el tamaño del gen pero viene de otro sitio.'),
     B('KpnI cuts at the start of the gene and SacI at the end. PstI cuts inside the gene, and SalI gives a piece the same size as the gene, but in the wrong place.', 'KpnI corta al principio del gen y SacI al final. PstI corta dentro del gen, y SalI da un trozo del mismo tamaño que el gen, pero en el sitio equivocado.'),
     B('Use KpnI and SacI together.', 'Usa KpnI y SacI juntas.')],
    [ex('jeans', B('The enzyme', 'La enzima'), B('From fungus to tank', 'Del hongo al tanque'), B('The cellulases used in factories are made in tanks by fungi that carry extra copies of the gene, so that they make large amounts of enzyme.', 'Las celulasas que se usan en las fábricas se fabrican en tanques con hongos que llevan copias extra del gen, para que produzcan mucha enzima.')),
     ex('dna', B('Look-alikes', 'Parecidos'), B('Size is not identity', 'El tamaño no es identidad'), B('Two different stretches of DNA can have the same length, and then they make the same band in the gel. The map tells them apart.', 'Dos tramos distintos de ADN pueden tener la misma longitud y entonces hacen la misma banda en el gel. El mapa los distingue.'))],
    org('cellulase-dna', 'DNA with the cellulase gene', 'ADN con el gen de la celulasa', 'Trichoderma reesei', B('A stretch of DNA of the fungus with a cellulase gene.', 'Un trozo de ADN del hongo con un gen de celulasa.'), ['Fungi', 'Ascomycota', 'Sordariomycetes', 'Hypocreales', 'Hypocreaceae', 'Trichoderma'], tissue='nucleus', organelle='nucleus'),
    **closing(B('The right piece, not just the right size', 'La pieza correcta, no solo el tamaño correcto'),
              B('You chose the pair that frees the gene and avoided a band that had its size but not its place.', 'Has elegido la pareja que libera el gen y has evitado una banda que tenía su tamaño pero no su sitio.'),
              B('Careful reading of maps and gels avoids mistakes that would cost weeks in a laboratory.', 'Leer con cuidado los mapas y los geles evita errores que costarían semanas en un laboratorio.'),
              B('Restriction enzymes were discovered in bacteria, which use them to cut the DNA of viruses. Werner Arber, Daniel Nathans and Hamilton Smith received the 1978 Nobel Prize in Physiology or Medicine for it.', 'Las enzimas de restricción se descubrieron en bacterias, que las usan para cortar el ADN de virus. Werner Arber, Daniel Nathans y Hamilton Smith recibieron el Premio Nobel de Fisiología o Medicina de 1978 por ello.'),
              B('Each enzyme recognises a short sequence, usually 4 to 8 letters, and cuts there. Gel electrophoresis separates the pieces by length only, so a band says how long a piece is, not which piece it is.', 'Cada enzima reconoce una secuencia corta, normalmente de 4 a 8 letras, y corta ahí. La electroforesis en gel separa los trozos solo por longitud, así que una banda dice cuánto mide un trozo, no qué trozo es.'),
              [B('The DNA is drawn as a straight stretch and the cutting positions are invented.', 'El ADN se dibuja como un trozo recto y las posiciones de corte son inventadas.'),
               B('Sizes are in kilobases (kb), thousands of letters.', 'Los tamaños están en kilobases (kb), miles de letras.')],
              []))

assert ('kpn', 'sac') in cut_check(cut_cellulase)[0] and not any(len(g) == 1 for g in cut_check(cut_cellulase)[0]) and cut_check(cut_cellulase)[1]

# ═════════════════════════ ASSEMBLE: Neandertal DNA ═════════════════════════

asm_neandertal = asm_spec('asm-neandertal', B('DNA from a cousin who is gone', 'ADN de un primo que ya no está'), B('A Neandertal, in short broken pieces', 'Un neandertal, en trozos cortos y rotos'), 'advanced', 9, 'dna',
    B('Rebuild a stretch of Neandertal DNA from seven short reads. A repeat can make two joins look right: check the length.', 'Reconstruye un trozo de ADN de neandertal a partir de siete lecturas cortas. Un repetido puede hacer que dos uniones parezcan correctas: comprueba la longitud.'),
    B('DNA taken from bones about forty thousand years old was read in millions of tiny, damaged pieces. Computers put them together, and the result could be compared with the genome of people today.', 'El ADN sacado de huesos de unos cuarenta mil años se leyó en millones de trozos diminutos y dañados. Los ordenadores los unieron, y el resultado se pudo comparar con el genoma de las personas de hoy.'),
    71, 54, 7, 4, True,
    org('neandertal-dna', 'Neandertal bone', 'Hueso de neandertal', 'Homo neanderthalensis', B('An extinct human relative that lived in Europe and Asia.', 'Un pariente humano extinto que vivió en Europa y Asia.'), MAMMAL + ['Primates', 'Hominidae', 'Homo'], tissue='bone'),
    [ex('dna', B('Old bones', 'Huesos viejos'), B('DNA that survived in a cave', 'ADN que sobrevivió en una cueva'), B('Bones from the cool, dry Vindija cave, in Croatia, kept some DNA. Most of what is in a bone like that comes from soil microbes, and the Neandertal part is broken into tiny pieces.', 'Los huesos de la cueva fresca y seca de Vindija, en Croacia, conservaron algo de ADN. La mayor parte de lo que hay en un hueso así viene de microbios del suelo, y la parte neandertal está rota en trozos diminutos.')),
     ex('dna', B('Repeats', 'Repetidos'), B('The hard part of assembly', 'Lo difícil del ensamblaje'), B('Genomes are full of repeated stretches. A fragment inside a repeat can match two different places, which is what makes assembly hard.', 'Los genomas están llenos de tramos repetidos. Un fragmento dentro de un repetido puede encajar en dos sitios distintos, y eso es lo que complica el ensamblaje.'))],
    B('Place the fragment that starts with ATG first. At the repeat, check which neighbour fits the following fragment too.', 'Pon primero el fragmento que empieza por ATG. En el repetido, mira qué vecino encaja también con el fragmento siguiente.'),
    repeat=5,
    **closing(B('A relative read from bones', 'Un pariente leído a partir de huesos'),
              B('You rebuilt a stretch of the DNA of an extinct relative of ours from short, overlapping pieces.', 'Has reconstruido un trozo del ADN de un pariente extinto nuestro a partir de trozos cortos que se solapan.'),
              B('Comparing our genome with the Neandertal one showed that many people today carry a small share of Neandertal DNA, which means that our ancestors had children with them.', 'Comparar nuestro genoma con el neandertal mostró que muchas personas de hoy llevan una pequeña parte de ADN neandertal, lo que significa que nuestros antepasados tuvieron hijos con ellos.'),
              B('In 2010 a team published the first draft of the Neandertal genome, based on bones of three individuals from Vindija cave, about 38,000 years old. People outside Africa carry roughly 1 to 4% of Neandertal ancestry.', 'En 2010 un equipo publicó el primer borrador del genoma neandertal, a partir de huesos de tres individuos de la cueva de Vindija, de unos 38 000 años. Las personas de fuera de África llevan aproximadamente entre un 1 y un 4 % de ascendencia neandertal.'),
              B('Ancient DNA is damaged: it is short, and some letters have chemically changed. Software has to filter out DNA from microbes and from the people who handled the bones, and then chain the overlapping reads.', 'El ADN antiguo está dañado: es corto y algunas letras han cambiado químicamente. Un programa tiene que filtrar el ADN de los microbios y de las personas que manipularon los huesos, y encadenar luego las lecturas que se solapan.'),
              [B('The fragments here have 8 to 14 letters; real ancient reads have around 50 to 100.', 'Los fragmentos de aquí tienen de 8 a 14 letras; las lecturas antiguas reales rondan las 50 a 100.'),
               B('The sequence is invented; only the way of rebuilding it is real.', 'La secuencia es inventada; solo es real la forma de reconstruirla.')],
              [ref(['Green, R. E.', 'Krause, J.', 'Briggs, A. W.', 'et al.'], 2010, 'A draft sequence of the Neandertal genome', 'Science', '10.1126/science.1188021')]))

# ═════════════════════════ CRISPR: a tomato and a pig ═════════════════════════

crispr_tomato = crispr_spec('crispr-8', B('A tomato with more GABA', 'Un tomate con más GABA'), B('Cutting the brake of an enzyme', 'Cortar el freno de una enzima'), 'intermediate', 8, 'tomato',
    B('Choose the guide that cuts inside the gene of an enzyme of the tomato, and only there.', 'Elige la guía que corta dentro del gen de una enzima del tomate, y solo ahí.'),
    B('GABA is a molecule that tomatoes make in small amounts. An enzyme makes it, and a short part of that enzyme acts as its own brake. Cutting the gene right there releases the brake, and the tomato makes much more GABA.', 'El GABA es una molécula que los tomates fabrican en pequeñas cantidades. Una enzima lo fabrica, y una parte corta de esa enzima actúa como su propio freno. Cortar el gen justo ahí suelta el freno, y el tomate fabrica mucho más GABA.'),
    org('tomato-gaba', 'Tomato', 'Tomate', 'Solanum lycopersicum', B('A fruit whose genes can be edited in the lab.', 'Una fruta cuyos genes se pueden editar en el laboratorio.'), PLANT + ['Magnoliopsida', 'Solanales', 'Solanaceae', 'Solanum'], tissue='fruit', organelle='nucleus'),
    [ex('tomato', B('The idea', 'La idea'), B('Release a brake', 'Soltar un freno'), B('Some enzymes have a short part that keeps them in check. Editing that part, without touching the rest, gives an enzyme that works all the time.', 'Algunas enzimas tienen una parte corta que las mantiene a raya. Editar esa parte, sin tocar el resto, da una enzima que trabaja todo el tiempo.')),
     ex('dna', B('The result', 'El resultado'), B('More of a natural molecule', 'Más de una molécula natural'), B('GABA is found in many foods. In edited tomatoes its content in the fruit rose many times over.', 'El GABA está en muchos alimentos. En los tomates editados su contenido en el fruto subió muchas veces.'))],
    B('the brake of the enzyme', 'el freno de la enzima'), 41, 100, 22, 62, 1,
    [('a', 'nopam'), ('b', 'offtarget'), ('c', 'perfect'), ('d', 'nomatch')],
    B('A stretch of the tomato gene for the enzyme that makes GABA. Edit the part that acts as a brake, and nothing else.', 'Un trozo del gen del tomate de la enzima que fabrica GABA. Edita la parte que actúa como freno, y nada más.'),
    [B('Tap each guide and count where it sticks. Only one cuts exactly once, inside the blue area.', 'Toca cada guía y cuenta dónde se pega. Solo una corta exactamente una vez, dentro de la zona azul.'),
     B('Look for the PAM, a letter and then GG, right after the place where the guide sticks. One guide has a look-alike site elsewhere.', 'Busca el PAM, una letra y luego GG, justo después del sitio donde se pega la guía. Una guía tiene un sitio parecido en otro lugar.'),
     B('Choose guide C.', 'Elige la guía C.')],
    **closing(B('A brake released', 'Un freno soltado'),
              B('You chose the guide that cuts inside the brake of the enzyme without touching other places.', 'Has elegido la guía que corta dentro del freno de la enzima sin tocar otros lugares.'),
              B('Tomatoes with more GABA reached the market in Japan in 2021, one of the first gene-edited foods to be sold.', 'Los tomates con más GABA llegaron al mercado en Japón en 2021, uno de los primeros alimentos editados genéticamente que se vendieron.'),
              B('In 2017 a Japanese team used CRISPR–Cas9 to edit a part of a tomato gene for an enzyme that makes GABA, and found that the fruits of the edited plants had many times the GABA of normal ones.', 'En 2017 un equipo japonés usó CRISPR–Cas9 para editar una parte de un gen del tomate que fabrica GABA, y comprobó que los frutos de las plantas editadas tenían muchas veces más GABA que los normales.'),
              B('Cutting inside the gene and letting the cell repair the cut changes a few letters. If the change removes the brake but keeps the rest of the enzyme, the enzyme is always on.', 'Cortar dentro del gen y dejar que la célula repare el corte cambia unas pocas letras. Si el cambio quita el freno pero conserva el resto de la enzima, la enzima queda siempre encendida.'),
              [B('Guides here have 8 letters so they fit on the screen; real ones have about 20.', 'Las guías de aquí tienen 8 letras para que quepan en pantalla; las reales tienen unas 20.'),
               B('The sequence is invented; only the idea is real.', 'La secuencia es inventada; solo la idea es real.')],
              [ref(['Nonaka, S.', 'Arai, C.', 'Takayama, M.', 'Matsukura, C.', 'Ezura, H.'], 2017, 'Efficient increase of γ-aminobutyric acid (GABA) content in tomato fruits by targeted mutagenesis', 'Scientific Reports', '10.1038/s41598-017-06400-y')]))

crispr_pig = crispr_spec('crispr-9', B('A pig that the virus cannot enter', 'Un cerdo en el que el virus no puede entrar'), B('Editing the door that a virus uses', 'Editar la puerta que usa un virus'), 'advanced', 9, 'cell',
    B('Choose the guide that edits the gene of the receptor that the virus uses, and only there.', 'Elige la guía que edita el gen del receptor que usa el virus, y solo ese.'),
    B('A virus of pigs enters their cells through a protein on the surface. Editing the part of the gene that the virus needs can give pigs that do not catch the disease, without adding genes from another species.', 'Un virus de los cerdos entra en sus células a través de una proteína de la superficie. Editar la parte del gen que necesita el virus puede dar cerdos que no contraen la enfermedad, sin añadir genes de otra especie.'),
    org('pig-cd163', 'Pig', 'Cerdo', 'Sus scrofa', B('A farm animal with a disease that costs a lot of money.', 'Un animal de granja con una enfermedad que cuesta mucho dinero.'), MAMMAL + ['Artiodactyla', 'Suidae', 'Sus'], tissue='lung cells', organelle='nucleus'),
    [ex('cell', B('The disease', 'La enfermedad'), B('A virus of pigs only', 'Un virus solo de cerdos'), B('The disease, called PRRS, makes sows lose their piglets and young pigs sick. It is one of the most costly diseases of pig farming, and it does not infect people.', 'La enfermedad, llamada PRRS, hace que las cerdas pierdan a sus lechones y que los cerdos jóvenes enfermen. Es una de las enfermedades más costosas de la cría de cerdos, y no infecta a las personas.')),
     ex('dna', B('The door', 'La puerta'), B('A receptor the virus needs', 'Un receptor que necesita el virus'), B('The virus attaches to a receptor called CD163 on a type of immune cell. Removing a small part of the receptor gives cells that the virus cannot enter, while the rest of the protein still works.', 'El virus se une a un receptor llamado CD163 de un tipo de célula inmune. Quitar una parte pequeña del receptor da células en las que el virus no puede entrar, mientras que el resto de la proteína sigue funcionando.')),
     ex('cell', B('Care', 'Cuidado'), B('Edit only the door', 'Editar solo la puerta'), B('A guide that cuts in other places of the genome could damage other genes. That is why only the guide that cuts exactly once, in the right place, is the right one.', 'Una guía que corta en otros lugares del genoma podría dañar otros genes. Por eso solo vale la guía que corta exactamente una vez, en el sitio justo.'))],
    B('the part of the receptor that the virus needs', 'la parte del receptor que necesita el virus'), 87, 112, 30, 74, 1,
    [('a', 'nomatch'), ('b', 'elsewhere'), ('c', 'nopam'), ('d', 'offtarget'), ('e', 'perfect')],
    B('A stretch of the pig gene for the receptor CD163. Edit the part that the virus needs, and nothing else.', 'Un trozo del gen del cerdo del receptor CD163. Edita la parte que necesita el virus, y nada más.'),
    [B('Tap each guide and count where it sticks. Only one cuts exactly once, inside the blue area.', 'Toca cada guía y cuenta dónde se pega. Solo una corta exactamente una vez, dentro de la zona azul.'),
     B('Two guides do not find a good site or a PAM, one cuts in another place and one cuts inside and also at a look-alike site elsewhere.', 'Dos guías no encuentran un buen sitio o un PAM, una corta en otro lugar y una corta dentro y también en un sitio parecido de otro sitio.'),
     B('Choose guide E.', 'Elige la guía E.')],
    **closing(B('A door closed to a virus', 'Una puerta cerrada a un virus'),
              B('You chose a guide that edits only the receptor that the virus needs.', 'Has elegido una guía que edita solo el receptor que necesita el virus.'),
              B('Disease-resistant livestock could mean fewer animals lost, less use of medicines and lower costs for farms.', 'Un ganado resistente a las enfermedades podría significar menos animales perdidos, menos uso de medicamentos y menores costes para las granjas.'),
              B('In 2016 a team reported pigs edited in the CD163 gene that were protected from the PRRS virus. Regulators later reviewed pigs edited in this way for food use.', 'En 2016 un equipo describió cerdos editados en el gen CD163 que quedaban protegidos del virus PRRS. Más tarde, algunos reguladores revisaron cerdos editados de esta forma para su uso como alimento.'),
              B('Cas9 cuts where the guide sticks if a PAM follows. The cell repairs the cut, often by deleting letters, which here removes the part of the receptor that the virus recognises.', 'Cas9 corta donde se pega la guía si le sigue un PAM. La célula repara el corte, a menudo borrando letras, lo que aquí quita la parte del receptor que reconoce el virus.'),
              [B('Guides here have 8 letters so they fit on the screen; real ones have about 20.', 'Las guías de aquí tienen 8 letras para que quepan en pantalla; las reales tienen unas 20.'),
               B('The sequence is invented; the real edit removes a stretch of a whole exon.', 'La secuencia es inventada; la edición real elimina un tramo de un exón entero.')],
              [ref(['Whitworth, K. M.', 'Rowland, R. R. R.', 'Ewen, C. L.', 'et al.'], 2016, 'Gene-edited pigs are protected from porcine reproductive and respiratory syndrome virus', 'Nature Biotechnology', '10.1038/nbt.3434')]))

write_levels([cut_cellulase, asm_neandertal, crispr_tomato, crispr_pig])
